import logging
from taf.sbts.oam.coam.admin.interfaces.admin_25r1 import SBTS25R1
from taf.sbts.oam.coam.admin.schemas.infomodel.object import InfoModelDistName
from taf.sbts.oam.coam.admin.schemas.infomodel.cell_22r3 import NrCellHardware, NrCellRuntime
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable, DataInconsistent
from taf.sbts.oam.coam.admin.schemas.procedure.lte_downlink_25r2 import LTEDownlink


class SBTS25R2(SBTS25R1):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS25R2, self).__init__(api_client)

    def collect_suppressed_alarm_history_file(self, target_file_name, timeout=120):
        """
        Collect Suppressed Alarm History file and save in provided path.

        :param str target_file_name: Suppressed alarm history filename.
        :param int timeout: (Optional) Timeout for the operation. Default set to 120 seconds.
        :return Union[str,dict]: Operation result as string i.e. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getSuppressedAlarms.html
        """
        self._api_client.execute_customer_procedure(name="getSuppressedAlarms",
                                                    parameters={"outputFileName": target_file_name},
                                                    timeout=timeout,
                                                    output_file_name=target_file_name)

    def export_nidd(self, json_file, timeout=60):
        """
        Export NIDD to .json file.

        :param str json_file: Path to the output NIDD .json file.
        :param int timeout: Timeout for the operation. Default set to 60 seconds.
        :return Union[str,dict]: Operation result as string i.e. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-exportNIDD.html
        """
        return self._api_client.execute_offline_procedure("exportNIDD", {}, timeout, output_file_name=json_file)

    def get_subcells_info(self, timeout=10):                    # noqa: C901
        """
        Get Subcell data of all available cells. Only supports 5G (NR).

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If 5G subcell data is not provided by M-Plane.
        :raise DataInconsistent: If 5G ADMIN or OAM Node-B provided information is incorrect with expected or faulty.
        :return dict: Dict structure where Key is cell group name and Value is structure with Realtime and Hardware
                                information for cells.

        Example of returned data:

        ::

        {
            u'NRCELLGRP-0': {
                u'NRCELL-1': {
                    'NRCELL_L': {
                         'distName': '/MRBTS-1/RAT-1/NRTS-1/NRBTS_L-1/NRCELL_L-1',
                         'parameters': {'lcrId': 1,
                                        'nrCellIdentity': 16385,
                                        'nrCellgrpDN': u'/MRBTS-1/RAT-1/NRTS-1/NRBTS_L-1/NRCELLGRP_L-0',
                                        'administrativeState': u'Locked',
                                        'availabilityStatus': None,
                                        'operationalState': u'Disabled',
                                        'usageState': u'Idle'}
                                        }
                    },
                    'NRCELL_R': {
                          'distName': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1',
                          'parameters': {'availabilityStatus': None,
                                         'bbModDNList': [],
                                         'frRefList': [],
                                         'nrCellIdentity': None,
                                         'operationalState': u'disabled',
                                         'proceduralStatus': None,
                                         'administrativeState': u'Unlocked',
                                         'blockingState': u'Unblocked',
                                         'usageState': u'Idle'}
                                        }
                    }
                }
            }
        }

        """
        bts_info = self.get_bts_info(timeout=timeout)

        if not bts_info.get("cellsGroup"):
            raise DataNotAvailable("Cell Group data containing subcell information was not provided by Node B OAM.")

        try:
            cell_groups_info = self.__get_cell_data_structure(cell_group_info=bts_info["cellsGroup"])
        except (KeyError, TypeError) as e:
            error_msg = "BTS cellsGroup information provided by OAM Node-B is inconsistent, or faulty. Error {}"
            raise DataInconsistent(error_msg.format(e))

        try:
            nr_cells_runtime = self.__get_infomodel_objects(
                object_type=NrCellRuntime,
                object_class_name="NRCELL_R",
                timeout=timeout)
        except DataInconsistent as e:
            logging.warning('Provided runtime cell structure info is inconsistent, faulty or missing. It will be ommited. Error {}'.format(e))
        else:
            self.__assign_realtime_cells(nr_cells_runtime, cell_groups_info)

        try:
            nr_cells_hardware = self.__get_infomodel_objects(
                object_type=NrCellHardware,
                object_class_name="NRCELL_L",
                timeout=timeout)
        except DataInconsistent as e:
            logging.warning('Provided hardware cell structure info is inconsistent, faulty or missing. It will be ommited. Error {}'.format(e))
        else:
            self.__assign_hardware_cells(nr_cells_hardware, cell_groups_info)

        return cell_groups_info

    def __assign_hardware_cells(self, nr_cells_hardware, cell_groups_info):
        for nr_cell in nr_cells_hardware:
            cell_group = InfoModelDistName(dist_name=nr_cell.nr_cellgrp_dn)
            self.__put_nr_cell_in_group(nr_cell, cell_groups_info, cell_group_name=cell_group.conf_name)

    def __assign_realtime_cells(self, nr_cells_runtime, cell_groups_info):
        for nr_cell in nr_cells_runtime:
            cell_group_name = self.__get_group_name_for_cell(
                cell_name=nr_cell.conf_name,
                cell_groups_info=cell_groups_info)
            if cell_group_name is None:
                error_msg = "Cell {cell_dist_name} returned by Node-B OAM, does not belong to any cell group"
                raise DataInconsistent(error_msg.format(cell_dist_name=nr_cell.dist_name))
            self.__put_nr_cell_in_group(nr_cell, cell_groups_info, cell_group_name=cell_group_name)

    def __get_group_name_for_cell(self, cell_name, cell_groups_info):
        for group_name, group_cells in cell_groups_info.items():
            if cell_name in group_cells:
                return group_name

    def __put_nr_cell_in_group(self, cell, cell_info, cell_group_name):
        cell_info[cell_group_name][cell.conf_name][cell.class_name] = cell.to_dict()

    def __get_cell_data_structure(self, cell_group_info):
        structure = {}
        for cell_group in cell_group_info:
            cell_group_name = cell_group["name"]

            if cell_group_name not in structure:
                structure[cell_group_name] = {}

            for cell_name in cell_group["nrCellList"]:
                structure[cell_group_name][cell_name] = {}

        return structure

    def __get_infomodel_objects(self, object_type, object_class_name, timeout):
        objects = []
        object_datas = self.get_managed_objects(class_name=object_class_name, timeout=timeout)

        for data in object_datas:
            objects.append(object_type.from_object_dict(data=data))
        return objects

    def get_subcells_status(self, timeout=10):
        """
        Get statuses for all subcells in cell groups.

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If 5G subcell data is not provided by M-Plane.
        :raise DataInconsistent: If 5G ADMIN or OAM Node-B provided information is incorrect with expected or faulty.
        :return dict: Dict structure where Key is cell group name and Value is structure with Realtime and Hardware
                                status names for cells.

        Example

        ::

        {
            u'NRCELLGRP-0': {
                u'NRCELL-1': {
                    'NRCELL_L': {
                        'administrativeState': u'Locked',
                        'availabilityStatus': None,
                        'operationalState': u'Disabled',
                        'usageState': u'Idle'
                    },
                    'NRCELL_R': {
                        'administrativeState': u'Unlocked',
                        'availabilityStatus': u'Failed',
                        'blockingState': u'Unblocked',
                        'operationalState': u'Disabled',
                        'usageState': u'Idle'
                    }
                }
            }
        }
        """
        cells_info = self.get_subcells_info(timeout=timeout)
        cells_statuses = {}

        try:
            for cell_group_name, cell_group_data in cells_info.items():
                cells_statuses[cell_group_name] = {}
                for cell_name, cell_data in cell_group_data.items():
                    cell_statuses = self.__get_statuses_for_cell(cell_data=cell_data)
                    cells_statuses[cell_group_name][cell_name] = cell_statuses

        except KeyError as e:
            raise DataInconsistent("Data provided by M-plane is inconsistent or faulty. Error {}".format(e))

        return cells_statuses

    def __get_statuses_for_cell(self, cell_data):
        cell_statuses = {}

        for cell_info_type, cell_type_data in cell_data.items():
            cell_statuses[cell_info_type] = cell_type_data["parameters"]

        return cell_statuses

    def start_downlink_test(self, dist_name, test_model, earfcn=None, phy_cell_id=None, p_max=None, connector_dn=None,
                            downlink_ch_bw=None, inband_prbi_index_dl=None, guardband_index_dl=None,
                            guardband_dl_freq_offset=None, tdd_frame_conf=None, tdd_spec_sub_conf=None,
                            laa_pattern_id=None, timeout=60, load_level=None):
        """
        Start LTE downlink test.

        :param str dist_name: LNCEL_R object to perform test on
        :param str test_model: (Optional) test_model. One of following:
                                                        "E_TM1_1" | "E_TM1_2" | "E_TM1_3" | "E_TM2" | "E_TM2a" | "E_TM3_1a" |
                                                         "E_TM3_1" | "E_TM3_2" | "E_TM3_3" | "MIMO_TM3_1" | "E_TM1_1_EE_LOW" |
                                                          "E_TM1_1_EE_MID" | "E_TM1_1_EE_HIGH" | "E_TM1_1_EE_HIGHER" | "E_TM1_1_EE_HIGHEST" |
                                                           "ChirpUp" | "ChirpDown" | "E_TM1_1_ETSI" | "IDLE_ACTIVE"
        :param int earfcn: (Optional) earfcn <0 to 262143>
        :param int phy_cell_id: (Optional) phy_cell_id <0 to 1007>
        :param int p_max: (Optional) p_max <0 to 60>
        :param str connector_dn: (Optional) connector_dn
        :param downlink_ch_bw: (Optional) downlink_ch_bw. One of following:
                                                          "NotDefined", "0_2MHz", "1_4MHz",
                                                          "3MHz", "5MHz", "10MHz", "15MHz",
                                                          "20MHz", "05_05MHz", "05_10MHz",
                                                          "10_05MHz", "10_10MHz"
        :param int inband_prbi_index_dl: (Optional) inband_prbi_index_dl <0 to 99>
        :param int guardband_index_dl: (Optional)  guardband_index_dl <0 to 99>
        :param int guardband_dl_freq_offset: (Optional) guardband_dl_freq_offset <-2147483648 to 2147483647>
        :param int tdd_frame_conf: (Optional) tdd_frame_conf <1 to 3>
        :param int tdd_spec_sub_conf: (Optional) tdd_spec_sub_conf <3 to 9>
        :param str laa_pattern_id: (Optional) laa_pattern_id. One of following: 'DTX', 'PCTX_7_3', 'PCTX_10_2'
        :param str load_level: (Optional) load level. loadLevel is only valid and must be configured when testModel is E_TM1_1_ETSI.
                               One of following: "load_0_low", "load_10", "load_30_medium", "load_50_busy_hour", "load_70".
        :param int timeout: (optional) Timeout for the operation. Defaults set to 60s.
        :return: It returns dict with data.

        Example response:
        {
            "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-1/START_LTE_DOWNLINK_TEST_IND-0",
            "confirmationNode": {
                "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-1/START_LTE_DOWNLINK_TEST_IND-0/ACK-0",
                "parameters": {}
            },
            "resultNode": {
                "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-1/START_LTE_DOWNLINK_TEST_IND-0/LTE_TEST_RESULT-0",
                "parameters": {
                    "status": "Succeeded",
                    "cause": null
                }
            }
        }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-startLteDownlinkTest.html
        """

        lte_downlink_schema = LTEDownlink(
            dist_name=dist_name,
            test_model=test_model,
            earfcn=earfcn,
            phy_cell_id=phy_cell_id,
            p_max=p_max,
            connector_dn=connector_dn,
            downlink_ch_bw=downlink_ch_bw,
            inband_prbi_index_dl=inband_prbi_index_dl,
            guardband_index_dl=guardband_index_dl,
            guardband_dl_freq_offset=guardband_dl_freq_offset,
            tdd_frame_conf=tdd_frame_conf,
            tdd_spec_sub_conf=tdd_spec_sub_conf,
            laa_pattern_id=laa_pattern_id,
            load_level=load_level
        )

        parameters = lte_downlink_schema.as_dict()

        return self._api_client.execute_procedure(name='startLteDownlinkTest',
                                                  parameters=parameters,
                                                  timeout=timeout)
